#!/usr/bin/env node
// Scatters pond and deep-water wildlife (object.water-life.*, generated by
// scripts/props/generate-water-life-scenes.mjs) over a world's water tiles as
// authored instances under a `water-life` Node2D.
//
// Shallow water: reeds and cattails along the shore, lily pads (some with a
// frog), waterweed, and fish whose whole swim path stays over water.
// Deep water: dark kelp, rising bubbles and a big fish shadow cruising below.
// Tiles near bridges and other placed objects are left clear. Deterministic;
// re-running replaces the previous water life. Dry run by default.
//
// Usage: node scripts/maps/scatter-water-life.mjs <world-id>... [--write]
import { readFileSync, writeFileSync } from 'node:fs';

const TILE = 64;
const GROUP_ID = 'water-life';
const ID_PREFIX = 'water-life-';
const LIFE = (name) => `object.water-life.${name}`;

const args = process.argv.slice(2);
const write = args.includes('--write');
const worlds = args.filter((argument) => !argument.startsWith('--'));
if (worlds.length === 0) throw new Error('Usage: node scripts/maps/scatter-water-life.mjs <world-id>... [--write]');

function unit(x, y, salt) {
  let hash = Math.imul(x + 0x3c6e, 0x27d4eb2d) ^ Math.imul(y - 0x1f83, 0x165667b1) ^ Math.imul(salt, 0x45d9f3b);
  hash = Math.imul(hash ^ (hash >>> 15), 0x2c1b3c6d);
  hash = Math.imul(hash ^ (hash >>> 12), 0x297a2d39);
  return ((hash ^ (hash >>> 15)) >>> 0) / 4294967296;
}
const hex8 = (text) => {
  let hash = 2166136261;
  for (const char of text) hash = Math.imul(hash ^ char.charCodeAt(0), 16777619);
  return (hash >>> 0).toString(16).padStart(8, '0');
};
const round = (value) => Math.round(value * 100) / 100;
const override = (sourceNodeId, property, value) => ({ sourceInstancePath: [], sourceNodeId, property, value });
const pickFrom = (list, roll) => list[Math.min(list.length - 1, Math.floor(roll * list.length))];
const instancePosition = (instance) => instance.overrides?.find((entry) => entry.sourceInstancePath.length === 0
  && entry.property === 'position' && ['body', 'root'].includes(entry.sourceNodeId))?.value;

const FISH = ['koi', 'carp', 'minnow', 'perch'];
const PADS = ['pink', 'white', 'single', 'small'];
const REEDS = ['cattails', 'reeds', 'rushes', 'sedge'];

for (const world of worlds) {
  const path = `src/game/content/scenes/authored/worlds/${world}.scene.json`;
  const text = readFileSync(path, 'utf8');
  const crlf = text.includes('\r\n');
  const scene = JSON.parse(text);
  const data = (scene.subresources ?? []).find((resource) => resource.kind === 'tile-data');
  if (!data) throw new Error(`${world}: no tile-data subresource`);
  const water = new Map();
  for (const cell of data.cells) {
    if (cell.tileId === 'water') water.set(`${cell.x},${cell.y}`, 'shallow');
    else if (cell.tileId === 'deep-water') water.set(`${cell.x},${cell.y}`, 'deep');
  }
  const kind = (x, y) => water.get(`${x},${y}`);

  scene.instances = (scene.instances ?? []).filter((instance) => !instance.instanceId.startsWith(ID_PREFIX));
  if (!scene.nodes.some((node) => node.id === GROUP_ID)) {
    const order = Math.max(-1,
      ...scene.nodes.filter((node) => node.parentId === 'world').map((node) => node.order),
      ...scene.instances.filter((instance) => instance.parentNodeId === 'world').map((instance) => instance.order)) + 1;
    scene.nodes.push({ id: GROUP_ID, name: 'Water Life', type: 'Node2D', parentId: 'world', order, properties: { position: [0, 0] } });
  }

  // Keep clear of placed objects, and well clear of bridges that span the water.
  const others = scene.instances.map((instance) => ({ at: instancePosition(instance), wide: /bridge|landmark/.test(instance.sceneId) })).filter((entry) => entry.at);
  const nearObject = (x, y) => others.some(({ at, wide }) => Math.hypot(at[0] - x, at[1] - y) < (wide ? 150 : 56));
  const placed = [];
  // Things only space out from their own group; fish may pass under lily pads.
  const spaced = (x, y, gap, swims) => placed.every((p) => p.swims !== swims || Math.hypot(p.x - x, p.y - y) >= Math.max(gap, p.gap));
  const added = [];
  const counts = {};
  const add = (name, x, y, gap, extra = []) => {
    // Spacing groups: big shadows, small fish, and everything that stays put.
    const swims = /deep-fish-shadow/.test(name) ? 'shadow' : /fish/.test(name) ? 'fish' : 'still';
    if (nearObject(x, y) || !spaced(x, y, gap, swims)) return false;
    placed.push({ x, y, gap, swims });
    const instanceId = `${ID_PREFIX}${hex8(`${world}:${name}:${Math.round(x)}:${Math.round(y)}`)}`;
    counts[name] = (counts[name] ?? 0) + 1;
    added.push({
      instanceId, name: instanceId, sceneId: LIFE(name), parentNodeId: GROUP_ID, order: added.length,
      persistenceKey: `${world}.${instanceId}`,
      overrides: [override('root', 'position', [round(x), round(y)]), ...extra],
    });
    return true;
  };
  /** True when every tile in the box around (tx, ty) is water (of `need` kind when given). */
  const pool = (tx, ty, rx, ry, need) => {
    for (let y = ty - ry; y <= ty + ry; y += 1) for (let x = tx - rx; x <= tx + rx; x += 1) {
      const k = kind(x, y);
      if (!k || (need && k !== need)) return false;
    }
    return true;
  };

  const cells = [...water.keys()].map((key) => key.split(',').map(Number)).sort((a, b) => a[1] - b[1] || a[0] - b[0]);
  // Swimmers first so plants make room for their paths' centres.
  for (const [x, y] of cells) {
    const cx = x * TILE + 32; const cy = y * TILE + 32;
    if (kind(x, y) === 'deep' && unit(x, y, 21) < 0.12) {
      // The big shadow keeps to deep water: its whole path must be deep.
      if (pool(x, y, 3, 1, 'deep') && unit(x, y, 22) < 0.5) add('deep-fish-shadow-lane', cx, cy, 420);
      else if (pool(x, y, 1, 1, 'deep') && pool(x, y, 2, 1)) add('deep-fish-shadow-oval', cx, cy, 420);
    } else if (unit(x, y, 11) < 0.18) {
      const species = pickFrom(FISH, unit(x, y, 12));
      // Open water fits either path; a one-row channel only fits the straight lane.
      if (pool(x, y, 2, 1)) add(`fish-${species}-${unit(x, y, 13) < 0.5 ? 'lane' : 'oval'}`, cx, cy, 170);
      else if (pool(x, y, 2, 0)) add(`fish-${species}-lane`, cx, cy, 170);
    }
  }
  // Every deep pool big enough gets at least one big shadow.
  if (!added.some((entry) => entry.sceneId.includes('deep-fish-shadow'))) {
    const spots = cells.filter(([x, y]) => kind(x, y) === 'deep' && pool(x, y, 1, 1, 'deep') && pool(x, y, 2, 1));
    // Try the most central spots first; some sit too close to a bridge.
    const middle = Math.floor(spots.length / 2);
    const order = spots.map((spot, index) => [Math.abs(index - middle), spot]).sort((a, b) => a[0] - b[0]).map(([, spot]) => spot);
    for (const [x, y] of order) if (add('deep-fish-shadow-oval', x * TILE + 32, y * TILE + 32, 420)) break;
  }
  for (const [x, y] of cells) {
    const k = kind(x, y);
    const jx = (unit(x, y, 2) - 0.5) * 30; const jy = (unit(x, y, 3) - 0.5) * 30;
    const cx = x * TILE + 32 + jx; const cy = y * TILE + 32 + jy;
    const flip = unit(x, y, 4) < 0.5 ? [override('visual', 'flipX', true)] : [];
    const land = [[-1, 0], [1, 0], [0, -1], [0, 1]].filter(([dx, dy]) => !kind(x + dx, y + dy));
    if (k === 'deep') {
      if (unit(x, y, 31) < 0.16) add(unit(x, y, 32) < 0.5 ? 'kelp-olive' : 'kelp-teal', cx, cy + 20, 70, flip);
      else if (unit(x, y, 33) < 0.07) add('bubbles', cx, cy + 10, 120);
      continue;
    }
    if (land.length) {
      // Reeds grow in the shallows right at the bank.
      if (unit(x, y, 41) < 0.32) {
        const [dx, dy] = land[Math.floor(unit(x, y, 42) * land.length)];
        add(`reeds-${pickFrom(REEDS, unit(x, y, 43))}`, x * TILE + 32 + dx * 20 + jx * 0.4, y * TILE + 32 + dy * 20 + 18, 46, flip);
        continue;
      }
    }
    const open = land.length === 0;
    if (unit(x, y, 51) < (open ? 0.13 : 0.08)) {
      if (unit(x, y, 52) < 0.3) add('frog-lilypad', cx, cy + 16, 90, flip);
      else add(`lilypad-${pickFrom(PADS, unit(x, y, 53))}`, cx, cy + 16, 60, flip);
    } else if (unit(x, y, 54) < (open ? 0.16 : 0.09)) {
      add(unit(x, y, 55) < 0.55 ? 'waterweed-eelgrass' : 'waterweed-bushy', cx, cy + 22, 60, flip);
    }
  }

  console.log(world, `${added.length} water-life`, Object.entries(counts).sort((a, b) => b[1] - a[1]).map(([name, count]) => `${name}:${count}`).join(' '));
  if (write) {
    scene.instances = [...scene.instances, ...added];
    const output = `${JSON.stringify(scene, null, 2)}\n`;
    writeFileSync(path, crlf ? output.replace(/\n/g, '\r\n') : output);
  }
}
if (!write) console.log('dry run: pass --write to apply');
